const data = $input.first().json;

// Get form values
const unitPrice = parseFloat(data['Unit Price (PKR)']);
const quantity = parseFloat(data['Quantity']);
const marginPct = parseFloat(data['Margin Percentage']);
const validityDays = parseInt(data['Validity Days']);

// Calculate prices
const costTotal = unitPrice * quantity;
const marginAmount = (costTotal * marginPct) / 100;
const sellingPricePerUnit = unitPrice * (1 + marginPct / 100);
const grandTotal = costTotal + marginAmount;

// Generate quote reference number
const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
const day = String(now.getDate()).padStart(2, '0');
const random = Math.floor(Math.random() * 9000) + 1000;
const quoteRef = `PRN-${year}${month}${day}-${random}`;

// Calculate validity date
const validityDate = new Date();
validityDate.setDate(validityDate.getDate() + validityDays);
const validityDateStr = validityDate.toLocaleDateString('en-PK', {
  day: '2-digit',
  month: 'long', 
  year: 'numeric',
  timeZone: 'Asia/Karachi'
});

// Format currency
function formatPKR(amount) {
  return 'PKR ' + amount.toLocaleString('en-PK', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  });
}

// Today's date
const todayStr = now.toLocaleDateString('en-PK', {
  day: '2-digit',
  month: 'long',
  year: 'numeric',
  timeZone: 'Asia/Karachi'
});

return [{
  json: {
    // Client Info
    clientName: data['Client Name'],
    clientEmail: data['Client Email'],

    // Product Info
    productDescription: data['Product Description'],
    quantity: quantity,
    specialNotes: data['Special Notes'] || '',

    // Pricing
    unitPrice: unitPrice,
    unitPriceFormatted: formatPKR(sellingPricePerUnit),
    grandTotal: grandTotal,
    grandTotalFormatted: formatPKR(grandTotal),

    // Quote Details
    quoteRef: quoteRef,
    quoteDate: todayStr,
    validityDate: validityDateStr,
    validityDays: validityDays,
  }
}];

const d = $input.first().json;

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: Arial, sans-serif; font-size: 13px; color: #1a1a1a; padding: 40px; }

  /* HEADER */
  .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px; }
  .logo-section { display: flex; align-items: center; gap: 15px; }
  .company-name { font-size: 22px; font-weight: bold; color: #1A3A6B; }
  .tagline { font-size: 11px; color: #888; letter-spacing: 2px; text-transform: uppercase; }
  .quote-badge { background: #1A3A6B; color: white; padding: 10px 20px; border-radius: 5px; text-align: center; }
  .quote-badge .label { font-size: 11px; opacity: 0.8; }
  .quote-badge .ref { font-size: 16px; font-weight: bold; margin-top: 4px; }

  /* DIVIDER */
  .divider { height: 3px; background: linear-gradient(to right, #1A3A6B, #E8A020); margin: 15px 0; }

  /* CONTACT BAR */
  .contact-bar { background: #f5f7fa; padding: 10px 15px; border-radius: 5px; display: flex; gap: 30px; margin-bottom: 20px; font-size: 12px; color: #555; }
  .contact-bar span { display: flex; align-items: center; gap: 5px; }

  /* DATE ROW */
  .date-row { display: flex; justify-content: space-between; margin-bottom: 20px; font-size: 12px; color: #555; }

  /* TO SECTION */
  .to-section { background: #EEF2FF; border-left: 4px solid #1A3A6B; padding: 15px; border-radius: 0 5px 5px 0; margin-bottom: 25px; }
  .to-section .to-label { font-size: 11px; color: #888; text-transform: uppercase; margin-bottom: 5px; }
  .to-section .client-name { font-size: 16px; font-weight: bold; color: #1A3A6B; }
  .to-section .client-email { font-size: 12px; color: #555; margin-top: 3px; }

  /* SUBJECT */
  .subject { font-size: 14px; font-weight: bold; color: #1A3A6B; margin-bottom: 20px; }

  /* TABLE */
  .quote-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
  .quote-table th { background: #1A3A6B; color: white; padding: 12px 10px; text-align: left; font-size: 12px; }
  .quote-table th:last-child { text-align: right; }
  .quote-table td { padding: 12px 10px; border-bottom: 1px solid #eee; font-size: 13px; }
  .quote-table td:last-child { text-align: right; font-weight: bold; }
  .quote-table tr:nth-child(even) { background: #f9f9f9; }

  /* TOTALS */
  .totals { display: flex; justify-content: flex-end; margin-bottom: 25px; }
  .totals-box { width: 300px; }
  .total-row { display: flex; justify-content: space-between; padding: 8px 10px; font-size: 13px; }
  .total-row.grand { background: #1A3A6B; color: white; border-radius: 5px; font-weight: bold; font-size: 14px; margin-top: 5px; }

  /* NOTES */
  .notes-section { background: #FFF8ED; border: 1px solid #F0C070; border-radius: 5px; padding: 15px; margin-bottom: 25px; }
  .notes-section .notes-title { font-weight: bold; color: #E8A020; font-size: 12px; margin-bottom: 8px; }

  /* TERMS */
  .terms { margin-bottom: 25px; }
  .terms-title { font-weight: bold; color: #1A3A6B; font-size: 12px; margin-bottom: 8px; border-bottom: 1px solid #eee; padding-bottom: 5px; }
  .terms ul { padding-left: 20px; }
  .terms ul li { font-size: 12px; color: #555; margin-bottom: 4px; }

  /* FOOTER */
  .footer-divider { height: 3px; background: linear-gradient(to right, #1A3A6B, #E8A020); margin: 20px 0 15px; }
  .footer { display: flex; justify-content: space-between; align-items: flex-end; }
  .signature-section { text-align: center; }
  .signature-line { width: 200px; border-top: 1px solid #333; margin: 40px auto 5px; }
  .signature-label { font-size: 11px; color: #555; }
  .footer-contact { font-size: 11px; color: #888; text-align: right; line-height: 1.8; }

  /* VALIDITY BADGE */
  .validity { display: inline-block; background: #E8F5E9; color: #2E7D32; border: 1px solid #A5D6A7; padding: 5px 12px; border-radius: 20px; font-size: 11px; font-weight: bold; margin-bottom: 20px; }
</style>
</head>
<body>

  <!-- HEADER -->
  <div class="header">
    <div class="logo-section">
      <div>
        <div class="company-name">PRONTA</div>
        <div class="tagline">Sourcing Redefined</div>
      </div>
    </div>
    <div class="quote-badge">
      <div class="label">QUOTATION</div>
      <div class="ref">${d.quoteRef}</div>
    </div>
  </div>

  <div class="divider"></div>

  <!-- CONTACT BAR -->
  <div class="contact-bar">
    <span>📞 +92 321 65 56 109</span>
    <span>✉️ sales@prontapk.com</span>
    <span>🌐 www.prontapk.com</span>
    <span>📍 Office # F-03, Nazir Center, 146 Ferozpur Road, Lahore</span>
  </div>

  <!-- DATE ROW -->
  <div class="date-row">
    <span><strong>Date:</strong> ${d.quoteDate}</span>
    <div class="validity">✓ Valid until: ${d.validityDate}</div>
  </div>

  <!-- TO SECTION -->
  <div class="to-section">
    <div class="to-label">Quotation Prepared For</div>
    <div class="client-name">${d.clientName}</div>
    <div class="client-email">${d.clientEmail}</div>
  </div>

  <!-- SUBJECT -->
  <div class="subject">Subject: Quotation for ${d.productDescription.substring(0, 60)}...</div>

  <!-- PRODUCTS TABLE -->
  <table class="quote-table">
    <thead>
      <tr>
        <th style="width:5%">#</th>
        <th style="width:55%">Product Description</th>
        <th style="width:10%">Qty</th>
        <th style="width:15%">Unit Price</th>
        <th style="width:15%">Total</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>01</td>
        <td>${d.productDescription}</td>
        <td>${d.quantity}</td>
        <td>${d.unitPriceFormatted}</td>
        <td>${d.grandTotalFormatted}</td>
      </tr>
    </tbody>
  </table>

  <!-- TOTALS -->
  <div class="totals">
    <div class="totals-box">
      <div class="total-row grand">
        <span>Grand Total</span>
        <span>${d.grandTotalFormatted}</span>
      </div>
    </div>
  </div>

  <!-- SPECIAL NOTES -->
  ${d.specialNotes ? `
  <div class="notes-section">
    <div class="notes-title">⚠️ Special Notes</div>
    <div>${d.specialNotes}</div>
  </div>` : ''}

  <!-- TERMS -->
  <div class="terms">
    <div class="terms-title">Terms & Conditions</div>
    <ul>
      <li>This quotation is valid for <strong>${d.validityDays} days</strong> from the date of issue.</li>
      <li>Prices are subject to change without prior notice after validity period.</li>
      <li>Payment terms: 50% advance, 50% before delivery.</li>
      <li>Delivery timeline starts after confirmation and advance payment.</li>
      <li>All disputes subject to Lahore jurisdiction.</li>
    </ul>
  </div>

  <!-- FOOTER -->
  <div class="footer-divider"></div>
  <div class="footer">
    <div class="signature-section">
      <div class="signature-line"></div>
      <div class="signature-label">Authorized Signatory</div>
      <div class="signature-label"><strong>PRONTA (Private) Limited</strong></div>
    </div>
    <div class="footer-contact">
      PRONTA (Private) Limited<br/>
      Office # F-03, Nazir Center<br/>
      146 Ferozpur Road, Lahore<br/>
      sales@prontapk.com | www.prontapk.com
    </div>
  </div>

</body>
</html>`;

return [{
  json: {
    html: html,
    clientName: d.clientName,
    clientEmail: d.clientEmail,
    quoteRef: d.quoteRef,
    grandTotalFormatted: d.grandTotalFormatted,
    quoteDate: d.quoteDate,
    validityDate: d.validityDate,
    productDescription: d.productDescription,
    specialNotes: d.specialNotes
  }
}];

